const saveCartItem = `-- name: SaveCartItem :one

INSERT INTO cart_saved_items (cart_id, product_sku, product_name, quantity)
VALUES ($1, $2, $3, $4)
ON CONFLICT (cart_id, product_sku) DO UPDATE SET quantity = EXCLUDED.quantity, product_name = EXCLUDED.product_name
RETURNING id, cart_id, product_sku, product_name, quantity, created_at
`

type SaveCartItemParams struct {
	CartID      uuid.UUID `json:"cart_id"`
	ProductSku  string    `json:"product_sku"`
	ProductName string    `json:"product_name"`
	Quantity    float64   `json:"quantity"`
}

// Save-for-later (cart-scoped, guest-capable)
// Parks a product off the cart - on conflict (same sku already saved) the
// quantity is replaced, not summed - saving a line twice isn't "add more"
func (q *Queries) SaveCartItem(ctx context.Context, arg SaveCartItemParams) (CartSavedItem, error) {
	row := q.db.QueryRowContext(ctx, saveCartItem,
		arg.CartID,
		arg.ProductSku,
		arg.ProductName,
		arg.Quantity,
	)
	var i CartSavedItem
	err := row.Scan(
		&i.ID,
		&i.CartID,
		&i.ProductSku,
		&i.ProductName,
		&i.Quantity,
		&i.CreatedAt,
	)
	return i, err
}

